1: // @ts-check
2: import Component from '@glimmer/component';
3: import { tracked } from '@glimmer/tracking';
4: import { task } from 'ember-concurrency';
5: import messageFromAdapterError from 'nomad-ui/utils/message-from-adapter-error';
6: import { alias } from '@ember/object/computed';
7: 
8: export default class JobStatusPanelComponent extends Component {
9:   @alias('args.job') job;
10:   @alias('args.handleError') handleError = () => {};
11: 
12:   // #region deployment
13:   @tracked oldVersionAllocBlockIDs = [];
14: 
15:   // Called via did-insert; sets a static array of "outgoing"
16:   // allocations we can track throughout a deployment
17:   establishOldAllocBlockIDs() {
18:     this.oldVersionAllocBlockIDs = this.job.allocations.filter(
19:       (a) =>
20:         a.clientStatus === 'running' &&
21:         a.jobVersion !== this.deployment.get('versionNumber')
22:     );
23:   }
24: 
25:   get isActivelyDeploying() {
26:     return this.job.get('latestDeployment.isRunning');
27:   }
28: 
29:   @task(function* () {
30:     try {
31:       yield this.job.latestDeployment.content.promote();
32:     } catch (err) {
33:       this.handleError({
34:         title: 'Could Not Promote Deployment',
35:         description: messageFromAdapterError(err, 'promote deployments'),
36:       });
37:     }
38:   })
39:   promote;
40: 
41:   @task(function* () {
42:     try {
43:       yield this.job.latestDeployment.content.fail();
44:     } catch (err) {
45:       this.handleError({
46:         title: 'Could Not Fail Deployment',
47:         description: messageFromAdapterError(err, 'fail deployments'),
48:       });
49:     }
50:   })
51:   fail;
52: 
53:   @alias('job.latestDeployment') deployment;
54:   @alias('deployment.desiredTotal') desiredTotal;
55: 
56:   get oldVersionAllocBlocks() {
57:     return this.job.allocations
58:       .filter((allocation) => this.oldVersionAllocBlockIDs.includes(allocation))
59:       .reduce((alloGroups, currentAlloc) => {
60:         (alloGroups[currentAlloc.clientStatus] =
61:           alloGroups[currentAlloc.clientStatus] || []).push(currentAlloc);
62:         return alloGroups;
63:       }, {});
64:   }
65: 
66:   get newVersionAllocBlocks() {
67:     let availableSlotsToFill = this.desiredTotal;
68:     let allocationsOfDeploymentVersion = this.job.allocations.filter(
69:       (a) => a.jobVersion === this.deployment.get('versionNumber')
70:     );
71:     // Only fill up to 100% of desiredTotal. Once we've filled up, we can stop counting.
72:     let allocationsOfShowableType = this.allocTypes.reduce((blocks, type) => {
73:       const jobAllocsOfType = allocationsOfDeploymentVersion.filterBy(
74:         'clientStatus',
75:         type.label
76:       );
77:       if (availableSlotsToFill > 0) {
78:         blocks[type.label] = Array(
79:           Math.min(availableSlotsToFill, jobAllocsOfType.length)
80:         )
81:           .fill()
82:           .map((_, i) => {
83:             return jobAllocsOfType[i];
84:           });
85:         availableSlotsToFill -= blocks[type.label].length;
86:       } else {
87:         blocks[type.label] = [];
88:       }
89:       return blocks;
90:     }, {});
91:     if (availableSlotsToFill > 0) {
92:       allocationsOfShowableType['unplaced'] = Array(availableSlotsToFill)
93:         .fill()
94:         .map(() => {
95:           return { clientStatus: 'unplaced' };
96:         });
97:     }
98:     return allocationsOfShowableType;
99:   }
100: 
101:   // #endregion deployment
102: 
103:   // Build note: allocTypes order matters! We will fill up to 100% of totalAllocs in this order.
104:   allocTypes = [
105:     'running',
106:     'pending',
107:     'failed',
108:     // 'unknown',
109:     // 'lost',
110:     // 'queued',
111:     // 'complete',
112:     'unplaced',
113:   ].map((type) => {
114:     return {
115:       label: type,
116:       property: `${type}Allocs`,
117:     };
118:   });
119: 
120:   get allocBlocks() {
121:     let availableSlotsToFill = this.totalAllocs;
122:     // Only fill up to 100% of totalAllocs. Once we've filled up, we can stop counting.
123:     let allocationsOfShowableType = this.allocTypes.reduce((blocks, type) => {
124:       const jobAllocsOfType = this.args.job.allocations.filterBy(
125:         'clientStatus',
126:         type.label
127:       );
128:       if (availableSlotsToFill > 0) {
129:         blocks[type.label] = Array(
130:           Math.min(availableSlotsToFill, jobAllocsOfType.length)
131:         )
132:           .fill()
133:           .map((_, i) => {
134:             return jobAllocsOfType[i];
135:           });
136:         availableSlotsToFill -= blocks[type.label].length;
137:       } else {
138:         blocks[type.label] = [];
139:       }
140:       return blocks;
141:     }, {});
142:     if (availableSlotsToFill > 0) {
143:       allocationsOfShowableType['unplaced'] = Array(availableSlotsToFill)
144:         .fill()
145:         .map(() => {
146:           return { clientStatus: 'unplaced' };
147:         });
148:     }
149:     return allocationsOfShowableType;
150:   }
151: 
152:   // TODO: eventually we will want this from a new property on a job.
153:   get totalAllocs() {
154:     // v----- Experimental method: Count all allocs. Good for testing but not a realistic representation of "Desired"
155:     // return this.allocTypes.reduce((sum, type) => sum + this.args.job[type.property], 0);
156: 
157:     // v----- Realistic method: Tally a job's task groups' "count" property
158:     return this.args.job.taskGroups.reduce((sum, tg) => sum + tg.count, 0);
159:   }
160: 
161:   get versions() {
162:     return Object.values(this.allocBlocks)
163:       .flat()
164:       .map((a) => (!isNaN(a?.jobVersion) ? `v${a.jobVersion}` : 'pending')) // "starting" allocs, and possibly others, do not yet have a jobVersion
165:       .reduce(
166:         (result, item) => ({
167:           ...result,
168:           [item]: [...(result[item] || []), item],
169:         }),
170:         []
171:       );
172:   }
173: }

