1: <div class="job-status-panel boxed-section {{if this.isActivelyDeploying "active-deployment is-info"}}" data-test-job-status-panel data-test-status-mode={{@statusMode}}>
2:   <div class="boxed-section-head"
3:     {{did-insert (optional (if this.isActivelyDeploying (action this.establishOldAllocBlockIDs)))}}
4:     {{did-update (optional (if this.isActivelyDeploying (action this.establishOldAllocBlockIDs))) this.isActivelyDeploying}}
5:   >
6:     {{#if this.isActivelyDeploying}}
7:       <div class="boxed-section-row">
8:         Deployment Status
9:         <span class="badge is-white bumper-left" data-test-active-deployment-stat="id">{{@job.latestDeployment.shortId}}</span>
10:         <div class="pull-right">
11:           {{#if @job.latestDeployment.isRunning}}
12:             <TwoStepButton
13:               data-test-fail
14:               @classes={{hash
15:                 idleButton="is-danger"
16:                 confirmationMessage="inherit-color"
17:                 confirmButton="is-danger"}}
18:               @idleText="Fail Deployment"
19:               @cancelText="Cancel"
20:               @confirmText="Yes, Fail Deployment"
21:               @confirmationMessage="Are you sure?"
22:               @inlineText={{true}}
23:               @awaitingConfirmation={{this.fail.isRunning}}
24:               @disabled={{this.fail.isRunning}}
25:               @onConfirm={{perform this.fail}} />
26:           {{/if}}
27:           {{#if @job.latestDeployment.requiresPromotion}}
28:             <button
29:               data-test-promote-canary
30:               type="button"
31:               class="button is-warning is-small {{if this.promote.isRunning "is-loading"}}"
32:               disabled={{this.promote.isRunning}}
